PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cafe_settings(id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cafe_tables(id INTEGER PRIMARY KEY, token TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS menu_categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ingredients(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES menu_categories(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL CHECK(price>=0), compare_at_price INTEGER CHECK(compare_at_price IS NULL OR compare_at_price>price), image TEXT NOT NULL DEFAULT '', pairing_product_id INTEGER REFERENCES products(id), pairing_reason TEXT NOT NULL DEFAULT '', available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), options TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS product_ingredients(product_id INTEGER REFERENCES products(id), ingredient_id INTEGER REFERENCES ingredients(id), PRIMARY KEY(product_id,ingredient_id));
CREATE TABLE IF NOT EXISTS staff_roles(id TEXT PRIMARY KEY CHECK(id IN('owner','staff')));
CREATE TABLE IF NOT EXISTS staff_profiles(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL REFERENCES staff_roles(id), password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('guest','customer','staff')), customer_id INTEGER REFERENCES customers(id), staff_id INTEGER REFERENCES staff_profiles(id), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS table_bills(id INTEGER PRIMARY KEY, table_id INTEGER REFERENCES cafe_tables(id), status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','PAID','CLOSED')), created_at INTEGER NOT NULL, paid_at INTEGER, closed_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_table_bill ON table_bills(table_id) WHERE status='OPEN';
CREATE TABLE IF NOT EXISTS bill_access(bill_id INTEGER REFERENCES table_bills(id), session_token TEXT REFERENCES sessions(token), PRIMARY KEY(bill_id,session_token));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, bill_id INTEGER NOT NULL REFERENCES table_bills(id), session_token TEXT NOT NULL REFERENCES sessions(token), customer_id INTEGER REFERENCES customers(id), source TEXT NOT NULL CHECK(source IN('CUSTOMER','COUNTER')), idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('CANCELLATION_PENDING','NEW','PREPARING','READY','SERVED','CANCELLED')), total INTEGER NOT NULL CHECK(total>=0), notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, deadline INTEGER NOT NULL, UNIQUE(session_token,idempotency_key));
CREATE INDEX IF NOT EXISTS orders_status_deadline ON orders(status,deadline);
CREATE INDEX IF NOT EXISTS orders_bill ON orders(bill_id);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 30), unit_price INTEGER NOT NULL CHECK(unit_price>=0), options TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, bill_id INTEGER NOT NULL REFERENCES table_bills(id), amount INTEGER NOT NULL CHECK(amount>=0), discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0), method TEXT NOT NULL CHECK(method IN('CASH','UPI')), reference TEXT NOT NULL DEFAULT '', staff_id INTEGER NOT NULL REFERENCES staff_profiles(id), idempotency_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, created_at INTEGER NOT NULL, voided_at INTEGER, void_reason TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_live_payment ON payments(bill_id) WHERE voided_at IS NULL;
CREATE TABLE IF NOT EXISTS loyalty_transactions(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), payment_id INTEGER REFERENCES payments(id), order_id INTEGER REFERENCES orders(id), coins INTEGER NOT NULL, reason TEXT NOT NULL, unique_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS loyalty_customer ON loyalty_transactions(customer_id);
CREATE TABLE IF NOT EXISTS reward_redemptions(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id), coins INTEGER NOT NULL CHECK(coins>0), value INTEGER NOT NULL CHECK(value>0), status TEXT NOT NULL CHECK(status IN('RESERVED','APPLIED','REVERSED')), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)), quantity_total INTEGER NOT NULL DEFAULT 1 CHECK(quantity_total BETWEEN 1 AND 50), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS game_requests(id INTEGER PRIMARY KEY, game_id INTEGER NOT NULL REFERENCES games(id), table_id INTEGER NOT NULL REFERENCES cafe_tables(id), session_token TEXT NOT NULL REFERENCES sessions(token), status TEXT NOT NULL CHECK(status IN('REQUESTED','DELIVERED','RETURNED')), created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_current_request ON game_requests(game_id,session_token) WHERE status!='RETURNED';
CREATE TABLE IF NOT EXISTS game_suggestions(id INTEGER PRIMARY KEY, name TEXT NOT NULL, normalized TEXT NOT NULL, customer_id INTEGER REFERENCES customers(id), session_token TEXT NOT NULL REFERENCES sessions(token), reviewed INTEGER NOT NULL DEFAULT 0, rewarded INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(session_token,normalized));
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, details TEXT NOT NULL, created_at INTEGER NOT NULL);
